-- ==============================================================================
-- SYNTHETIC DATASET EXPANSION: 03_expand_sample_data.sql
-- Smart Campus Management System — XYZ University
--
-- PURPOSE:
--   Substantially expands the university academic and examination database
--   with relationally consistent, realistic synthetic records across all 14 tables.
--
-- SAFETY & IDEMPOTENCY:
--   - Does NOT drop or truncate any existing tables or records.
--   - Uses existence checks (MERGE / WHERE NOT EXISTS) to guarantee safe re-execution.
--   - Strict enforcement of foreign keys, check constraints, and business rules:
--       * Classes_Attended <= Classes_Held
--       * Offerings enrollment <= Max_Seats
--       * Exam End_Time > Start_Time
--       * Marks and results respect grading scale (S, A, B, C, D, F)
-- ==============================================================================

SET DEFINE OFF;
SET SERVEROUTPUT ON SIZE UNLIMITED;
SET LINESIZE 200;

PROMPT ==================================================================;
PROMPT  EXPANDING SYNTHETIC DATASET FOR XYZ UNIVERSITY...;
PROMPT ==================================================================;

-- 1. DEPARTMENTS
PROMPT Inserting Departments...;

-- 2. PROGRAMS
PROMPT Inserting Programs...;

-- 3. FACULTY
PROMPT Inserting Faculty Members...;

-- 4. COURSES
PROMPT Inserting Courses...;

-- 5. COURSE OFFERINGS
PROMPT Inserting Course Offerings...;

-- 6. STUDENTS
PROMPT Inserting Students...;

-- 7. ENROLLMENTS
PROMPT Inserting Course Enrollments...;

-- 8. ATTENDANCE
PROMPT Inserting Attendance Records...;

-- 9. MARKS
PROMPT Inserting Continuous Assessment & Exam Marks...;

-- 10. EXAMINATIONS
PROMPT Inserting Examination Timetables...;

-- 11. EXAM REGISTRATIONS
PROMPT Inserting Exam Registrations...;

-- 12. EXAM RESULTS
PROMPT Inserting Published Examination Results...;

-- 13. RE-EXAMINATION APPLICATIONS
PROMPT Inserting Re-Exam Applications...;

COMMIT;

PROMPT ==================================================================;
PROMPT  DATABASE EXPANSION COMPLETE. VERIFYING ROW COUNTS:;
PROMPT ==================================================================;

SELECT 'DEPARTMENT' AS tbl, COUNT(*) AS cnt FROM DEPARTMENT
UNION ALL SELECT 'PROGRAM', COUNT(*) FROM PROGRAM
UNION ALL SELECT 'STUDENT', COUNT(*) FROM STUDENT
UNION ALL SELECT 'FACULTY', COUNT(*) FROM FACULTY
UNION ALL SELECT 'COURSE', COUNT(*) FROM COURSE
UNION ALL SELECT 'COURSE_OFFERING', COUNT(*) FROM COURSE_OFFERING
UNION ALL SELECT 'ENROLLMENT', COUNT(*) FROM ENROLLMENT
UNION ALL SELECT 'ATTENDANCE', COUNT(*) FROM ATTENDANCE
UNION ALL SELECT 'MARKS', COUNT(*) FROM MARKS
UNION ALL SELECT 'GRADE', COUNT(*) FROM GRADE
UNION ALL SELECT 'EXAM', COUNT(*) FROM EXAM
UNION ALL SELECT 'EXAM_REGISTRATION', COUNT(*) FROM EXAM_REGISTRATION
UNION ALL SELECT 'EXAM_RESULT', COUNT(*) FROM EXAM_RESULT
UNION ALL SELECT 'RE_EXAM_APPLICATION', COUNT(*) FROM RE_EXAM_APPLICATION;
